  const HORM = (d) => { const F = 0.3 + 0.7 * Math.exp(-Math.pow((d - 19) / 2.5, 2)) + 0.5 * Math.exp(-Math.pow((d - 2) / 2, 2)), E = 0.15 + 0.85 * Math.exp(-Math.pow((d - 20.2) / 1.4, 2)) + 0.85 * Math.exp(-Math.pow((d + 0.8) / 1.4, 2)), L = 0.08 + 0.95 * Math.exp(-Math.pow((d - 21) / 0.5, 2)) + 0.95 * Math.exp(-Math.pow(d / 0.5, 2)), P = 0.05 + 0.9 * clamp(Math.sin(Math.PI * clamp((d - 3) / 15, 0, 1)), 0, 1); return { F, E, L, P }; };
  AK.def2d("H3-b", { title: "Roles of hormones in reproduction", label: "Oestrous cycle hormones",
    blurb: "Hormone levels across a cow's 21-day oestrous cycle. Move the day to see which hormone is in charge.", vars: [{ key: "d", label: "Day of cycle", min: 0, max: 21, step: 0.5, value: 20 }],
    draw(g, s, c, B) { const A = AK.axes(B, 12, 12, 380, B.H - 26, { x0: 0, x1: 21, y0: 0, y1: 1.1, nx: 7, xl: "Day of oestrous cycle (heat on day 0 / 21)", yl: "Relative level", title: "Hormones in the oestrous cycle" }); [["F", "FSH", B.P.blue], ["E", "Oestrogen", B.P.red], ["L", "LH", B.P.amber], ["P", "Progesterone", B.P.green]].forEach(([k, n, col], i) => { AK.curve(B, A, (d) => HORM(d)[k], 0, 21, col, 2.4, 120); B.text("— " + n, A.px + 8, A.py + 12 + i * 14, { size: 10.5, color: col }); }); B.line(A.X(c.d), A.py, A.X(c.d), A.py + A.ph, B.P.ink, 1.5, [4, 3]); const H = HORM(c.d), top = Object.entries(H).sort((a, b) => b[1] - a[1])[0][0];
      AK.side(B, "Day " + c.d, [[{ F: "FSH: stimulates follicle growth in the ovary", E: "Oestrogen: produced by the follicle; causes heat (oestrus) signs", L: "LH: triggers ovulation and forms the corpus luteum", P: "Progesterone: from the corpus luteum; prepares and maintains the uterus for pregnancy" }[top], "#ffd27a", true], "Testosterone: male characteristics and sperm production.", "Oxytocin: milk let-down and uterine contractions at birth.", "Prolactin: milk production.", "If no pregnancy, prostaglandin destroys the corpus luteum and a new cycle starts."]); },
    readouts: (s, c) => { const H = HORM(c.d); return [["Day", c.d], ["FSH", f(H.F, 2)], ["Oestrogen", f(H.E, 2)], ["LH", f(H.L, 2)], ["Progesterone", f(H.P, 2)]]; },
    story: [{ d: 6, cap: "Early in the cycle FSH makes a follicle grow in the ovary.", set: { d: 2 } }, { d: 6, cap: "In mid-cycle the corpus luteum makes progesterone, which prepares the uterus.", set: { d: 11 } }, { d: 6, cap: "As the follicle matures, oestrogen rises: the cow shows signs of heat.", set: { d: 20 } }, { d: 6, cap: "An LH surge releases the egg: ovulation. Inseminate in the second half of heat.", set: { d: 21 } }],
    tasks: ["At which day does each hormone peak?", "State the role of FSH, LH, oestrogen, progesterone, oxytocin and prolactin."] });
