    controls: [{ type: "tabs", key: "sp", label: "Species", options: Object.entries(SPEC).map(([k, v]) => [k, v[0]]) }],
    draw(g, s, c, B) { g.save(); g.translate(0, 22); const S = SPEC[c.sp], x0 = B.area.x + 6, w = B.area.w - 12, X = (d) => x0 + (d / 365) * w; B.text("Year planner — " + S[0], x0, 22, { size: 12, w: 700 }); g.fillStyle = "rgba(120,140,200,.15)"; g.fillRect(x0, 34, w, 26); if (S[1]) for (let d = 5; d < 365; d += S[1]) { g.fillStyle = "#d84a5a"; g.fillRect(X(d), 34, Math.max(2, X(S[2] / 24) - X(0)), 26); } const due = c.mate + S[3]; B.line(X(c.mate), 30, X(c.mate), 66, B.P.blue, 3); B.text("mate", X(c.mate), 78, { size: 10.5, align: "center", color: B.P.blue }); g.fillStyle = "rgba(80,170,90,.35)"; g.fillRect(X(c.mate), 90, X(Math.min(365, due)) - X(c.mate), 18); B.text("gestation " + S[3] + " days", X(c.mate) + 6, 103, { size: 10.5, halo: false }); const dd = due > 365 ? due - 365 : due; B.text("birth: day " + dd + (due > 365 ? " (next year)" : ""), X(Math.min(365, due)), 124, { size: 11, w: 700, align: due > 300 ? "right" : "left" });
      AK.btable(B, 16, 140, [110, 90, 90, 90], [["Species", "Cycle (days)", "Heat (hours)", "Gestation (days)"]].concat(Object.values(SPEC).map((v) => [v[0], v[1] || "induced", v[2] || "—", v[3]])), { hi: Object.keys(SPEC).indexOf(c.sp) + 1 }); g.restore(); AK.side(B, "Signs of heat", [S[4], "Colostrum: first milk, rich in antibodies; give to the young within 6 hours.", "Lactation follows parturition; mammary glands produce milk."]); },
