    build(S, s) { const g = BK.group(S, s); AK.ground(g, { w: 6, d: 4, amp: 0.01, tex: "concrete_floor_worn_001" }); g.add(AK.building("shed", { w: 3.4, d: 2.4, h: 1.8 })); s.cow = AK.animal("holstein"); g.add(s.cow); s.sweat = GK.particles(80, 0xcfe6ff, 0.03, 0.6); g.add(s.sweat); },
    update(S, s, c, dt) { s.t = (s.t || 0) + dt; const pant = clamp((c.t - 25) / 12, 0, 1); if (s.cow) { s.cow.head.rotation.z = -0.1 * pant + 0.05 * Math.sin(s.t * (2 + pant * 10)); s.cow.scale.y = 1 + 0.01 * Math.sin(s.t * (2 + pant * 10)); } for (let i = 0; i < 80; i++) { const u = (i / 80 + s.t * 0.3) % 1; s.sweat.pos[i * 3] = 1.2 + u * 0.3 + (pant > 0.2 ? 0 : 99); s.sweat.pos[i * 3 + 1] = 1.0 + u * 0.4; s.sweat.pos[i * 3 + 2] = Math.sin(i) * 0.1; } s.sweat.flush(); },
    hud: (s, c) => { const z = c.t < 5 ? "cold stress" : c.t <= 25 ? "comfort zone (thermoneutral)" : c.t <= 32 ? "mild heat stress" : "severe heat stress"; return [{ title: c.t + " °C — " + z, lines: [["Heat gain (sun, metabolism) vs heat loss (sweating, panting, radiation)", "#ffd27a", true], c.t > 25 ? "Responses: panting, sweating, seeking shade, drinking more, eating less." : "Little effort needed to keep body temperature at about 38.5 °C."] }]; },
